                         param3: float = 0, param4: float = 0, param5: float = 0,
                         param6: float = 0, param7: float = 0) -> dict:
        """Send MAVLink COMMAND_LONG message."""
        if not self.connection_handler.is_connected():
            return {
                'success': False,
                'message': 'Not connected to drone',
                'ack_received': False
            }

